const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const washington = ee.FeatureCollection("TIGER/2018/States")
                       .filter(ee.Filter.eq('NAME', 'Washington'))
                       .geometry();

  const date1 = '2021-11-15';
  const date2 = '2021-11-22';

  const dataset = 'NASA_USDA/HSL/SMAP_soil_moisture';
  const band = 'ssm'; // Surface soil moisture

  // 2. Data Acquisition & Processing
  function getMeanSoilMoisture(date) {
    const imageCollection = ee.ImageCollection(dataset)
      .filterDate(date)
      .select(band);

    const size = imageCollection.size().getInfo();
    if (size === 0) {
      return { 'size': 0 };
    }

    const image = imageCollection.first();

    const stats = image.reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: washington,
      scale: 9000, // SMAP native resolution is ~9km
      maxPixels: 1e9
    });

    return {
        'size': size,
        'mean': stats.get(band + '_mean'),
        'pixels': stats.get(band + '_count')
    };
  }

  const results1 = getMeanSoilMoisture(date1);
  const results2 = getMeanSoilMoisture(date2);

  // 3. Validation & Final Answer
  if (results1.size === 0 || results2.size === 0) {
    console.log(`Image count on ${date1}: ${results1.size}`);
    console.log(`Image count on ${date2}: ${results2.size}`);
    console.log("Empty Collection: No images found for one or both dates.");
    console.log("C1");
    return;
  }

  const mean1 = ee.Number(results1.mean).getInfo();
  const pixels1 = ee.Number(results1.pixels).getInfo();
  const mean2 = ee.Number(results2.mean).getInfo();
  const pixels2 = ee.Number(results2.pixels).getInfo();

  console.log(`${date1} Mean Moisture (ssm): ${mean1 !== null ? mean1.toFixed(3) : 'N/A'}, Pixels: ${pixels1}`);
  console.log(`${date2} Mean Moisture (ssm): ${mean2 !== null ? mean2.toFixed(3) : 'N/A'}, Pixels: ${pixels2}`);

  if (pixels1 === 0 || pixels2 === 0) {
    console.log("No Valid Pixels: All pixels were masked for one or both dates.");
    console.log("C2");
    return;
  }

  if (mean1 === null || mean2 === null) {
    console.log("Calculation Failure: Could not compute mean value.");
    console.log("C3");
    return;
  }

  if (mean2 > mean1) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
    console.error(`An error occurred: ${e}`);
    console.log("D");
});
